 Button Button(string title,EventHandler click){var b=new SoftButton{Text=title,AutoSize=false,Width=Math.Max(96,TextRenderer.MeasureText(title,Font).Width+30),Margin=new Padding(0,0,8,7),Primary=title=="开始扫描"||title=="＋ 文件"||title=="运行卸载",Danger=title.Contains("永久删除")||title.Contains("清理勾选")||title.Contains("强制结束")};b.Click+=click;actions.Add(b);return b;}
 Panel Page(){var p=new Panel{Dock=DockStyle.Fill,Visible=false};pages.Add(p);body.Controls.Add(p);return p;}
 Label Note(string text,int height){return new Label{Text="提示  /  "+text,Dock=DockStyle.Top,Height=height,Padding=new Padding(14,10,12,7),BackColor=Color.FromArgb(229,241,237),ForeColor=Color.FromArgb(63,104,98)};}
