 internal void ShowPage(int i){for(int j=0;j<pages.Count;j++){pages[j].Visible=j==i;((NavButton)nav[j]).Active=j==i;nav[j].Invalidate();}pages[i].BringToFront();string[] h={"让电脑，轻装上阵。","文件处理","软件卸载","软件残留","空间整理","开机启动","备份与日志","关于景·除"};string[] d={"每一次清理，都清楚而从容。","先预览，再处理。支持长路径、异常名称与占用查询。","调用软件原卸载器，完成后再决定是否清理残留。","按关键词查找候选项，逐项核对后再清理。","发现临时文件、空文件夹、大文件与零字节文件。","注册表启动项与启动文件夹，一处管理。","注册表先备份再修改，每次操作留下记录。","以清晰设计，做好每一次删除。"};heading.Text=h[i];subtitle.Text=d[i];}
 void Say(string text){if(IsDisposed)return;if(InvokeRequired){BeginInvoke(new Action<string>(Say),text);return;}if(output.TextLength>60000)output.Clear();output.AppendText(DateTime.Now.ToString("HH:mm:ss")+"  "+text+Environment.NewLine);Engine.Log(text);}
 void Progress(string text){if(IsDisposed)return;BeginInvoke(new Action(()=>status.Text="处理中 · "+text));}
 async void Work(string title,Action<CancellationToken> task) {
  if(busy)return;busy=true;cts=new CancellationTokenSource();foreach(var b in actions)b.Enabled=false;cancel.Enabled=true;status.Text=title;Say(title);
  try{await StaTask(()=>task(cts.Token));Say("本次操作结束，请检查逐项结果。");}catch(OperationCanceledException){Say("已取消后续步骤；已完成的删除或重启排程不会撤销。");}catch(Exception e){Say("未完成："+e.Message);BrandDialogs.Show(e.Message,"操作未完成",MessageBoxButtons.OK,MessageBoxIcon.Warning);}finally{busy=false;foreach(var b in actions)b.Enabled=true;cancel.Enabled=false;status.Text="就绪 · "+(Engine.Admin?"管理员模式":"普通用户模式");cts.Dispose();cts=null;}
 }
 public static string Ask(IWin32Window parent,string title,string message,string value,bool multiline=false){using(var f=new Form{Text=title,ClientSize=new Size(650,multiline?420:355),BackColor=Look.Canvas,StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,Font=new Font("Microsoft YaHei UI",10F)}){f.Controls.Add(new Label{Text=title,Font=new Font(f.Font.FontFamily,17F,FontStyle.Bold),ForeColor=Look.Ink,Location=new Point(24,18),Size=new Size(596,38)});var label=new TextBox{Text=message,Multiline=true,ReadOnly=true,BorderStyle=BorderStyle.None,BackColor=Look.Canvas,ForeColor=Look.Muted,ScrollBars=ScrollBars.Vertical,Location=new Point(26,70),Size=new Size(594,155)};var t=new TextBox{Text=value,Multiline=multiline,ScrollBars=multiline?ScrollBars.Vertical:ScrollBars.None,Location=new Point(26,238),Size=new Size(594,multiline?100:30)};var ok=new SoftButton{Text="确定",Primary=true,DialogResult=DialogResult.OK,Location=new Point(400,f.ClientSize.Height-58),Size=new Size(104,38)};var no=new SoftButton{Text="取消",DialogResult=DialogResult.Cancel,Location=new Point(516,f.ClientSize.Height-58),Size=new Size(104,38)};f.Controls.AddRange(new Control[]{label,t,ok,no});if(!multiline)f.AcceptButton=ok;f.CancelButton=no;f.Shown+=(s,e)=>t.Focus();return BrandDialogs.ShowForm(f,parent)==DialogResult.OK?t.Text:null;}}
 bool Confirm(string title,string details,bool typed){if(typed)return Ask(this,title,details+"\n\n请输入 DELETE 确认：","")=="DELETE";return BrandDialogs.Show(this,details,title,MessageBoxButtons.OKCancel,MessageBoxIcon.Warning)==DialogResult.OK;}
 void BuildFiles(){var p=Page();p.Controls.Add(Note("拖拽到窗口任意位置，或添加文件/文件夹。链接只处理链接本身，不递归进入链接目标。\n永久删除不会进入回收站；失败或取消时可能已删除部分内容。",65));var bar=Toolbar(p,94);
  bar.Controls.Add(Button("＋ 文件",(s,e)=>{using(var d=new OpenFileDialog{Multiselect=true,CheckFileExists=false})if(d.ShowDialog()==DialogResult.OK)AddFiles(d.FileNames);}));
