 void AddFiles(IEnumerable<string> paths){foreach(string raw in paths){try{string p=Engine.Validate(raw);if(files.Items.Cast<ListViewItem>().Any(x=>string.Equals((string)x.Tag,p,StringComparison.OrdinalIgnoreCase)))continue;string info;try{info=Engine.Describe(p);}catch(Exception e){info="读取失败："+e.Message;}var row=new ListViewItem(new[]{p,info}){Tag=p,Checked=true,ToolTipText=p};files.Items.Add(row);}catch(Exception e){Say("未添加："+raw+" · "+e.Message);}}}
 string[] FileTargets(){var a=files.CheckedItems.Cast<ListViewItem>().Select(x=>(string)x.Tag).ToArray();if(a.Length==0)BrandDialogs.Show("请先勾选目标项目。","景·除");return a;}
 void FileResult(string path,string text){BeginInvoke(new Action(()=>{foreach(ListViewItem x in files.Items)if((string)x.Tag==path){x.SubItems[1].Text=text;if(text.StartsWith("完成"))x.Checked=false;}}));}
 void DeleteFiles(int mode){var a=FileTargets();if(a.Length==0)return;if(mode==2&&!Engine.Admin){BrandDialogs.Show("重启后删除需要管理员权限，请先点击右上角重启。","景·除");return;}string verb=mode==0?"移入回收站":mode==1?"永久删除":"安排在下次 Windows 启动时删除";
  if(!Confirm(verb,"将"+verb+"以下 "+a.Length+" 个目标及其内容：\n"+string.Join("\n",a.Take(4))+(a.Length>4?"\n……":"")+(mode==2?"\n排程成功不代表最终一定删除；不自动重启。该操作没有内置撤销。":""),mode!=0))return;
  bool fix=repair.Checked;Work(verb,t=>{int ok=0,fail=0;foreach(string p in a){t.ThrowIfCancellationRequested();try{if(mode==0)Engine.Recycle(p);else{long n=Engine.Delete(p,fix,mode==2,t,x=>Progress(x));Say((mode==2?"已排程 ":"已删除 ")+n+" 项："+p);}ok++;FileResult(p,mode==2?"完成：已排程，待重启验证":"完成：已删除/移入回收站");}catch(OperationCanceledException){throw;}catch(Exception e){fail++;Say("失败："+p+" · "+e.Message);FileResult(p,"失败："+e.Message);}}Say("成功 "+ok+"；失败 "+fail);});
 }
 void MoveOne(){if(files.SelectedItems.Count!=1){BrandDialogs.Show("请选中一行进行重命名或移动。","景·除");return;}string p=(string)files.SelectedItems[0].Tag;string dest=Ask(this,"重命名 / 同卷移动","输入目标完整路径。不会覆盖已有目标；跨磁盘移动不支持。",p);if(string.IsNullOrWhiteSpace(dest)||dest==p)return;if(!Confirm("移动项目",p+"\n→ "+dest,false))return;Work("移动项目",t=>{Engine.Rename(p,dest);Say("已移动至："+dest);BeginInvoke(new Action(()=>{foreach(ListViewItem r in files.Items)if((string)r.Tag==p){r.Tag=dest;r.Text=dest;r.SubItems[1].Text="已移动";}}));});}
 void FindLocks(){var a=FileTargets();if(a.Length==0)return;Work("查询占用进程",t=>{var result=Engine.Lockers(a,t);BeginInvoke(new Action(()=>ShowLocks(result)));});}
 void ShowLocks(List<Native.ProcessInfo> result){if(result.Count==0){Say("未发现 Restart Manager 可识别的占用进程；这不代表文件一定未被占用。");return;}using(var f=new Form{Text="占用进程 · 请先保存其他软件的工作",Width=760,Height=430,StartPosition=FormStartPosition.CenterParent,Font=Font,BackColor=paper,Padding=new Padding(18)}){var list=new ListView{Dock=DockStyle.Fill,View=View.Details,FullRowSelect=true};list.Columns.Add("PID",80);list.Columns.Add("程序",300);list.Columns.Add("服务",230);Look.NiceList(list);foreach(var x in result)list.Items.Add(new ListViewItem(new[]{x.process.pid.ToString(),x.app,x.service}){Tag=x});var close=new SoftButton{Text="请求所选程序正常关闭",Dock=DockStyle.Bottom,Height=36};close.Click+=(s,e)=>{if(list.SelectedItems.Count!=1)return;var x=(Native.ProcessInfo)list.SelectedItems[0].Tag;try{using(var proc=Process.GetProcessById(x.process.pid)){long stamp=((long)(uint)x.process.start.dwHighDateTime<<32)|(uint)x.process.start.dwLowDateTime;if(proc.StartTime.ToFileTimeUtc()!=stamp)throw new Exception("进程已经变化，请重新扫描。");Say(proc.CloseMainWindow()?"已发送正常关闭请求。":"该进程没有可关闭的主窗口。");}}catch(Exception ex){BrandDialogs.Show(ex.Message);}};var kill=new SoftButton{Danger=true,Text="强制结束所选进程",Dock=DockStyle.Bottom,Height=36};kill.Click+=(s,e)=>{if(list.SelectedItems.Count!=1)return;var x=(Native.ProcessInfo)list.SelectedItems[0].Tag;if(!Confirm("强制结束进程","未保存的数据可能丢失："+x.app+" ("+x.process.pid+")",true))return;try{Engine.Terminate(x);list.SelectedItems[0].Remove();Say("已结束："+x.app);}catch(Exception ex){BrandDialogs.Show(ex.Message);}};f.Controls.Add(list);f.Controls.Add(close);f.Controls.Add(kill);BrandDialogs.ShowForm(f,this);}}
 void BuildApps(){var p=Page();p.Controls.Add(Note("先运行官方卸载，再按需要扫描残留。此列表来自传统桌面软件卸载登记，不列出全部商店应用。\n支持复选框勾选（优先）或 Ctrl / Shift 多选卸载；勾选跨搜索保留。",65));var bar=Toolbar(p,55);search=new TextBox{Width=245,Margin=new Padding(0,3,8,0)};search.TextChanged+=(s,e)=>FilterApps();bar.Controls.Add(search);bar.Controls.Add(Button("刷新列表",(s,e)=>ReloadApps()));bar.Controls.Add(Button("运行卸载",(s,e)=>Uninstall()));bar.Controls.Add(Button("查看安装目录",(s,e)=>{var a=SelectedApp();if(a!=null){if(Directory.Exists(a.Location))Process.Start("explorer.exe",Engine.Quote(a.Location));else BrandDialogs.Show("安装目录未登记或不存在。");}}));bar.Controls.Add(Button("扫描此软件残留",(s,e)=>{var a=SelectedApp();if(a!=null){keyword.Text=a.Name;ShowPage(3);ScanResidue();}}));bar.Controls.Add(Button("勾选当前列表",(s,e)=>{foreach(ListViewItem r in apps.Items)r.Checked=true;}));bar.Controls.Add(Button("清空全部勾选",(s,e)=>{checkedAppIds.Clear();FilterApps();}));apps=List(p,new[]{"软件名称","版本","发布者","范围"},new[]{340,110,230,130},true);apps.ItemChecked+=(s,e)=>{if(updatingApps||!(e.Item.Tag is InstalledApp))return;string id=AppIdentity((InstalledApp)e.Item.Tag);if(e.Item.Checked)checkedAppIds.Add(id);else checkedAppIds.Remove(id);};}
 InstalledApp SelectedApp(){if(apps.SelectedItems.Count!=1){BrandDialogs.Show("请先选中一个软件。");return null;}return (InstalledApp)apps.SelectedItems[0].Tag;}
 void ReloadApps(){Work("读取软件卸载登记与图标",t=>{var a=Engine.Apps();var icons=new List<Bitmap>();try{foreach(var app in a){t.ThrowIfCancellationRequested();icons.Add(SoftwareIcons.Load(app));}BeginInvoke(new Action(()=>{SetInstalledApps(a,icons);Say("找到 "+a.Count+" 个卸载登记；图标已加载。");}));}catch{foreach(var image in icons)image.Dispose();throw;}});}
 void SetInstalledApps(List<InstalledApp> entries,List<Bitmap> icons){
  var images=new ImageList{ColorDepth=ColorDepth.Depth32Bit,ImageSize=new Size(32,34)};
  for(int i=0;i<icons.Count;i++)images.Images.Add(icons[i]);
  var old=apps.SmallImageList;var previous=appIconBitmaps;
  updatingApps=true;apps.BeginUpdate();try{apps.Items.Clear();apps.SmallImageList=images;installed=entries;checkedAppIds.IntersectWith(entries.Select(AppIdentity));appIconBitmaps=icons;appIconIndices.Clear();for(int i=0;i<entries.Count;i++)appIconIndices[entries[i]]=i;FilterApps();}finally{apps.EndUpdate();updatingApps=false;}
  if(old!=null)old.Dispose();foreach(var image in previous)image.Dispose();
 }
 void FilterApps(){if(apps==null)return;updatingApps=true;apps.BeginUpdate();apps.Items.Clear();foreach(var a in installed.Where(x=>(x.Name+" "+x.Publisher).IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0)){int index;apps.Items.Add(new ListViewItem(new[]{a.Name,a.Version,a.Publisher,(a.Hive==RegistryHive.CurrentUser?"当前用户":"所有用户")+" / "+(a.View==RegistryView.Registry64?"64":"32")}){Tag=a,Checked=checkedAppIds.Contains(AppIdentity(a)),ImageIndex=appIconIndices.TryGetValue(a,out index)?index:-1,ToolTipText=a.Name});}apps.EndUpdate();updatingApps=false;}
 static string AppIdentity(InstalledApp a){return a.Hive+"|"+a.View+"|"+a.KeyPath+"|"+a.Name+"|"+a.Command;}
 List<InstalledApp> UninstallTargets(){return checkedAppIds.Count>0?installed.Where(a=>checkedAppIds.Contains(AppIdentity(a))).ToList():apps.SelectedItems.Cast<ListViewItem>().Select(x=>(InstalledApp)x.Tag).ToList();}
 void Uninstall(){var queue=Engine.PrepareUninstallQueue(UninstallTargets());if(queue.Count==0){BrandDialogs.Show("请选择一个或多个软件，可按 Ctrl / Shift 多选。");return;}if(!Confirm("依次卸载所选软件","将按顺序处理 "+queue.Count+" 个软件：\n"+string.Join("\n\n",queue.Select(a=>a.Name+"\n"+a.Command))+"\n\n请在各卸载器中完成操作。卸载后的注册表候选项会统一列出，由你确认删除。取消后续处理会停止队列，但不结束当前卸载器。",false))return;Work("依次卸载并检测注册表残留",token=>{var results=new List<RegItem>();var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var app in queue){if(token.IsCancellationRequested&&results.Count>0)BeginInvoke(new Action(()=>ShowUninstallResidues(new InstalledApp{Name="已完成卸载的候选残留"},results)));token.ThrowIfCancellationRequested();try{using(var process=Engine.Uninstall(app)){Say("正在卸载："+app.Name+"，请在卸载器窗口完成操作。");int code=Engine.WaitForUninstall(process,token);Say(app.Name+" 卸载器退出码："+code);if(code==1602||code==1223){Say("已取消该软件卸载，继续后续队列。");continue;}if(Engine.UninstallEntryExists(app)){bool done=(bool)Invoke(new Func<bool>(()=>Confirm("核对卸载已完成",app.Name+"\n卸载登记仍存在。可能卸载失败，或转交给其他卸载进程。\n请等待所有相关卸载窗口结束。确定：扫描并继续队列；取消：停止后续队列。",false)));if(!done){Say("已停止后续卸载队列。");break;}}foreach(var r in Engine.ScanAfterUninstall(app,token)){string id=r.Hive+"|"+r.View+"|"+r.Path;if(seen.Add(id)){r.Description="来源："+app.Name+"；"+r.Description;results.Add(r);}}}}catch(OperationCanceledException){if(results.Count>0)BeginInvoke(new Action(()=>ShowUninstallResidues(new InstalledApp{Name="已完成卸载的候选残留"},results)));throw;}catch(Exception ex){Say("卸载未完成："+app.Name+" · "+ex.Message);}}token.ThrowIfCancellationRequested();BeginInvoke(new Action(()=>ShowUninstallResidues(new InstalledApp{Name=queue.Count==1?queue[0].Name:"批量卸载结果"},results)));});}
 void ShowUninstallResidues(InstalledApp app,List<RegItem> candidates){keyword.Text=Engine.ResidualName(app.Name);residue.BeginUpdate();residue.Items.Clear();foreach(var r in candidates)residue.Items.Add(new ListViewItem(new[]{r.ToString(),"注册表","卸载后候选："+app.Name+"；"+r.Description}){Tag=r,Checked=false});residue.EndUpdate();ShowPage(3);Say("卸载后自动扫描完成："+candidates.Count+" 个候选注册表键。未删除任何注册表内容。请逐项勾选后点击清理勾选项确认。");if(candidates.Count==0)BrandDialogs.Show("未发现名称匹配的候选注册表残留。扫描不是全注册表检测；可修改关键词再次扫描。","卸载后检测完成");}
 void BuildResidue(){var p=Page();p.Controls.Add(Note("扫描当前用户/本机 SOFTWARE 下的直接子键、卸载登记，以及常见安装与数据目录的第一层文件夹。\n所有结果初始不勾选。共享厂商目录可能属于多个软件；仅删除你确认的项目。",65));var bar=Toolbar(p,55);keyword=new TextBox{Width=250,Margin=new Padding(0,3,8,0)};bar.Controls.Add(keyword);bar.Controls.Add(Button("扫描候选残留",(s,e)=>ScanResidue()));bar.Controls.Add(Button("查看选中项",(s,e)=>{if(residue.SelectedItems.Count==1){var r=residue.SelectedItems[0];BrandDialogs.Show(r.Text+"\n\n"+r.SubItems[2].Text,"候选项详情");}}));bar.Controls.Add(Button("清理勾选项",(s,e)=>CleanResidue()));residue=List(p,new[]{"候选路径 / 注册表键","类型","匹配说明"},new[]{510,90,260},true);}
 void ScanResidue(){string term=keyword.Text.Trim();if(term.Length<3){BrandDialogs.Show("请输入至少 3 个字符的软件独有关键词。");return;}Work("扫描候选残留："+term,t=>{var regs=Engine.ScanRegistry(term);t.ThrowIfCancellationRequested();var folders=Engine.ScanFolders(term);BeginInvoke(new Action(()=>{residue.Items.Clear();foreach(var r in regs)residue.Items.Add(new ListViewItem(new[]{r.ToString(),"注册表",r.Description}){Tag=r});foreach(var f in folders)residue.Items.Add(new ListViewItem(new[]{f,"文件夹","目录名称匹配；清理会永久删除全部内容"}){Tag=f});Say("扫描完成："+(regs.Count+folders.Count)+" 个候选项；请逐项核对并勾选。");}));});}
 void CleanResidue(){var rows=residue.CheckedItems.Cast<ListViewItem>().ToArray();if(rows.Length==0){BrandDialogs.Show("请核对并勾选需要清理的候选项。");return;}if(!Confirm("清理软件残留","将清理 "+rows.Length+" 个勾选项目。\n注册表键先备份再删除；文件夹永久删除全部内容。\n删除卸载登记不会卸载软件。\n"+string.Join("\n",rows.Take(3).Select(x=>x.Text)),true))return;var objects=rows.Select(x=>x.Tag).ToArray();Work("清理勾选的残留",t=>{for(int i=0;i<objects.Length;i++){t.ThrowIfCancellationRequested();object obj=objects[i];try{if(obj is RegItem)Engine.RemoveRegistry((RegItem)obj);else Engine.Delete((string)obj,false,false,t,Progress);int index=i;BeginInvoke(new Action(()=>{rows[index].Checked=false;rows[index].SubItems[2].Text="清理完成";}));Say("已清理："+obj);}catch(OperationCanceledException){throw;}catch(Exception ex){Say("未清理："+obj+" · "+ex.Message);}}});}
 void BuildBackups(){var p=Page();p.Controls.Add(Note("备份仅包含注册表修改前导出的键；不包含被删文件，也不记录文件权限的原始状态。\n恢复会把备份内容合并到注册表。恢复本机范围的备份可能需要管理员权限。",65));var bar=Toolbar(p,92);bar.Controls.Add(Button("刷新备份",(s,e)=>LoadBackups()));bar.Controls.Add(Button("恢复选中备份",(s,e)=>{if(backups.SelectedItems.Count!=1){BrandDialogs.Show("请选择一个备份。");return;}Restore((string)backups.SelectedItems[0].Tag);}));bar.Controls.Add(Button("导入其他 .reg",(s,e)=>{using(var d=new OpenFileDialog{Filter="注册表备份|*.reg"})if(d.ShowDialog()==DialogResult.OK)Restore(d.FileName);}));bar.Controls.Add(Button("打开备份目录",(s,e)=>OpenFolder(Engine.BackupDir)));bar.Controls.Add(Button("打开日志目录",(s,e)=>OpenFolder(Engine.LogDir)));bar.Controls.Add(Button("导出今日日志",(s,e)=>{using(var d=new SaveFileDialog{Filter="文本日志|*.log",FileName="景·除-"+DateTime.Now.ToString("yyyyMMdd")+".log"})if(d.ShowDialog()==DialogResult.OK){try{string source=Path.Combine(Engine.LogDir,DateTime.Now.ToString("yyyy-MM-dd")+".log");if(File.Exists(source))File.Copy(source,d.FileName,true);else File.WriteAllText(d.FileName,"今日暂无日志。",Encoding.UTF8);Say("日志已导出："+d.FileName);}catch(Exception ex){BrandDialogs.Show(ex.Message);}}}));backups=List(p,new[]{"备份文件","修改前键 / 说明"},new[]{330,530},false);}
 void OpenFolder(string path){Directory.CreateDirectory(path);Process.Start("explorer.exe",Engine.Quote(path));}
 void LoadBackups(){try{Directory.CreateDirectory(Engine.BackupDir);backups.Items.Clear();foreach(var f in Directory.GetFiles(Engine.BackupDir,"*.reg").OrderByDescending(x=>x)){string info=File.Exists(f+".txt")?File.ReadAllText(f+".txt"):"外部备份";backups.Items.Add(new ListViewItem(new[]{Path.GetFileName(f),info.Replace(Environment.NewLine," / ")}){Tag=f});}}catch(Exception e){BrandDialogs.Show(e.Message);}}
 void Restore(string f){if(!Confirm("恢复注册表备份","仅导入可信备份。此操作会合并/覆盖备份中的注册表值。\n"+f+"\n本工具文件名 -32.reg 使用 32 位视图，其余使用系统原生视图。",true))return;Work("导入注册表备份",t=>{Engine.Restore(f);Say("已导入："+f);});}
 void Elevate(){if(busy)return;if(Engine.Admin){BrandDialogs.Show("当前已经是管理员模式。");return;}if(!Confirm("以管理员身份重启","系统将显示 UAC 授权窗口。当前列表不会保留；备份和日志仍保存在原位置。",false))return;try{Process.Start(new ProcessStartInfo(Application.ExecutablePath){UseShellExecute=true,Verb="runas"});Close();}catch(Exception e){BrandDialogs.Show(e.Message);}}
}
}
